import type { CreateHost, Host, NodeView, Outcome } from '../host.ts';

const MIN_TERM = 0;
const MAX_TERM = 3;
const OTHER_NODES = ['n1', 'n2'] as const;

type Role = NodeView['role'];
type Vote = NodeView['votedFor'];
type OtherNode = (typeof OTHER_NODES)[number];

const ok = (): Outcome => ({ ok: true });
const refuse = (reason: string): Outcome => ({ ok: false, reason });

const isTerm = (t: unknown): t is number =>
  typeof t === 'number' && Number.isInteger(t) && t >= 1 && t <= MAX_TERM;
const isOtherNode = (c: unknown): c is OtherNode =>
  typeof c === 'string' && (OTHER_NODES as readonly string[]).includes(c);

const createHost: CreateHost = async () => {
  let role: Role = 'follower';
  let term = MIN_TERM;
  let votedFor: Vote = 'nobody';

  const host: Host = {
    async electionTimeout() {
      if (role === 'shutdown') return refuse('the node is shut down');
      if (role === 'leader') return refuse('the leader does not time out');
      if (term >= MAX_TERM) return refuse(`no term after ${MAX_TERM}`);
      role = 'candidate';
      term += 1;
      votedFor = 'itself';
      return ok();
    },

    async electionWon() {
      if (role === 'shutdown') return refuse('the node is shut down');
      if (role !== 'candidate') return refuse('only a candidate can win an election');
      role = 'leader';
      return ok();
    },

    async newerTermSeen(t: number) {
      if (role === 'shutdown') return refuse('the node is shut down');
      if (!isTerm(t)) return refuse(`the term must be an integer from 1 to ${MAX_TERM}`);
      if (t <= term) return refuse('the term is not newer than the node\'s term');
      role = 'follower';
      term = t;
      votedFor = 'nobody';
      return ok();
    },

    async quorumLost() {
      if (role === 'shutdown') return refuse('the node is shut down');
      if (role !== 'leader') return refuse('only the leader can lose its quorum');
      role = 'follower';
      return ok();
    },

    async shutdown() {
      if (role === 'shutdown') return refuse('the node is already shut down');
      role = 'shutdown';
      return ok();
    },

    async voteRequested(candidate: string, t: number) {
      if (role === 'shutdown') return refuse('the node is shut down');
      if (!isOtherNode(candidate)) return refuse('the candidate must be n1 or n2');
      if (!isTerm(t)) return refuse(`the term must be an integer from 1 to ${MAX_TERM}`);
      if (t > term) {
        role = 'follower';
        term = t;
        votedFor = candidate;
        return ok();
      }
      if (t < term) return refuse('the term is older than the node\'s term');
      if (role !== 'follower') return refuse('only a follower grants its vote in its own term');
      if (votedFor !== 'nobody' && votedFor !== candidate) {
        return refuse('the node already voted in this term');
      }
      votedFor = candidate;
      return ok();
    },

    async node() {
      return { role, term, votedFor };
    },
  };

  return host;
};

export default createHost;

